(() => {
  const AA = window.FLYDIY_AA, R = window.FLYDIY_RENDERER, P = window.FLIGHT_PROBE;
  if (!AA || !R) return 'no FLYDIY_AA / FLYDIY_RENDERER';
  if (window.__BLUE) return 'sampler already on';
  const gl = R.getContext(), S = window.__BLUE = { n: 0, flat: [], ctx: [], t0: performance.now(), last: null, err: null };
  const prev = AA.render, px = new Uint8Array(4);
  const PTS = [[.2,.12],[.5,.12],[.8,.12],[.2,.3],[.5,.3],[.8,.3],[.35,.45],[.65,.45],[.5,.2]];
  AA.render = function () {
    const r = prev.apply(this, arguments);
    try {
      const c = R.domElement, w = c.width, h = c.height; gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      let lo = [255,255,255], hi = [0,0,0];
      for (const [fx, fy] of PTS) { gl.readPixels((w * fx) | 0, (h * fy) | 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
        for (let k = 0; k < 3; k++) { if (px[k] < lo[k]) lo[k] = px[k]; if (px[k] > hi[k]) hi[k] = px[k]; } }
      S.n++; S.last = [lo, hi];
      if (hi[0] - lo[0] <= 8 && hi[1] - lo[1] <= 8 && hi[2] - lo[2] <= 8) {
        const t = Math.round(performance.now() - S.t0);
        S.flat.push([t, S.n, lo[0], lo[1], lo[2]]);
        if (S.ctx.length < 6) { let o = { t, n: S.n, rgb: lo.slice(), calls: R.info.render.calls };
          try { const g = P.camGet(), e = g.eye, wd = P.world(); o.eye = e.map(v => +v.toFixed(1)); o.groundUnderEye = wd && wd.terrainH ? +wd.terrainH(e[0], e[2]).toFixed(1) : null; o.agl = +(+P.agl()).toFixed(1); o.cam = P.camModeNow(); } catch (x) { o.ctxErr = String(x.message); }
          S.ctx.push(o); }
      }
    } catch (e) { S.err = String(e && e.message); }
    return r;
  };
  return 'picture sampler on (9 pixels a frame)';
})()

(() => { const S = window.__BLUE; if (!S) return 'no sampler';
  const runs = []; let cur = null;
  for (const f of S.flat) { if (cur && f[1] === cur.n1 + 1) { cur.n1 = f[1]; cur.t1 = f[0]; } else { cur = { t0: f[0], t1: f[0], n0: f[1], n1: f[1], rgb: [f[2], f[3], f[4]] }; runs.push(cur); } }
  return JSON.stringify({ frames: S.n, flatFrames: S.flat.length, runs: runs.slice(0, 12).map(r => ({ atMs: r.t0, frames: r.n1 - r.n0 + 1, lastsMs: r.t1 - r.t0, rgb: r.rgb })), ctx: S.ctx, err: S.err, lastRange: S.last }); })()
